cypress_script:
describe('Checkout Overview and Totals', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    // Assuming items have been added to the cart before reaching this page
    cy.visit('https://www.saucedemo.com/checkout-step-two.html');
  });

  it('should display the checkout overview with correct totals', () => {
    cy.url().should('include', '/checkout-step-two.html');
    cy.get('[data-test="secondary-header"]').should('be.visible');
    cy.get('[data-test="cart-list"]').should('be.visible');
    cy.get('[data-test="payment-info-label"]').should('contain', 'Payment Information:');
    cy.get('[data-test="payment-info-value"]').should('contain', 'SauceCard #31337');
    cy.get('[data-test="shipping-info-label"]').should('contain', 'Shipping Information:');
    cy.get('[data-test="shipping-info-value"]').should('contain', 'Free Pony Express Delivery!');
    cy.get('[data-test="total-label"]').should('contain', 'Total: $0.00');
  });

  it('should allow user to cancel the checkout process', () => {
    cy.get('#cancel').click();
    cy.url().should('not.include', '/checkout-step-two.html');
    cy.url().should('include', '/cart.html'); // Assuming it redirects to cart page
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Checkout Overview and Totals', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
    // Assuming items have been added to the cart before reaching this page
    await page.goto('https://www.saucedemo.com/checkout-step-two.html');
  });

  test('should display the checkout overview with correct totals', async ({ page }) => {
    await expect(page).toHaveURL(/checkout-step-two.html/);
    await expect(page.locator('[data-test="secondary-header"]').isVisible()).toBeTruthy();
    await expect(page.locator('[data-test="cart-list"]').isVisible()).toBeTruthy();
    await expect(page.locator('[data-test="payment-info-label"]').textContent()).resolves.toContain('Payment Information:');
    await expect(page.locator('[data-test="payment-info-value"]').textContent()).resolves.toContain('SauceCard #31337');
    await expect(page.locator('[data-test="shipping-info-label"]').textContent()).resolves.toContain('Shipping Information:');
    await expect(page.locator('[data-test="shipping-info-value"]').textContent()).resolves.toContain('Free Pony Express Delivery!');
    await expect(page.locator('[data-test="total-label"]').textContent()).resolves.toContain('Total: $0.00');
  });

  test('should allow user to cancel the checkout process', async ({ page }) => {
    await page.click('#cancel');
    await expect(page).not.toHaveURL(/checkout-step-two.html/);
    await expect(page).toHaveURL(/cart.html/); // Assuming it redirects to cart page
  });
});
